// TIGHT COUPLING - Bad: OrderService knows concrete class
class OrderService {
    private MySQLOrderRepository repository;

    public OrderService() {
        this.repository = new MySQLOrderRepository(); // Direct instantiation - tightly coupled
    }

    public void processOrder(Long orderId) {
        repository.save(orderId); // Can't swap implementation, hard to test
    }
}

// LOOSE COUPLING - Good: Depend on interface
interface OrderRepository {
    void save(Long orderId);
}

@Service
class OrderService {
    private final OrderRepository repository; // Interface, not concrete class

    public OrderService(OrderRepository repository) { // Spring injects any implementation
        this.repository = repository;
    }

    public void processOrder(Long orderId) {
        repository.save(orderId); // Works with MySQL, Mongo, or mock
    }
}

// LOW COHESION - Bad: unrelated responsibilities in one class
@Service
class UserService {
    public void authenticateUser(String username, String password) { /* auth logic */ }
    public void sendWelcomeEmail(String email) { /* email logic */ }
    public void generateUserReport(Long userId) { /* reporting logic */ }
    public void logActivity(String message) { /* logging logic */ }
    // Nothing relates to anything else - low cohesion
}

// HIGH COHESION - Good: each class has one clear purpose
@Service
class UserAuthenticationService {
    public void authenticate(String username, String password) { /* auth logic */ }
    public void logout(String token) { /* logout logic */ }
    public boolean validateToken(String token) { /* validation logic */ }
    // All methods serve authentication - high cohesion
}

@Service
class EmailNotificationService {
    public void sendWelcomeEmail(String email) { /* email logic */ }
    public void sendPasswordResetEmail(String email) { /* reset logic */ }
    // All methods serve email notifications - high cohesion
}

// GOD CLASS - Antipattern: does everything
@Service
class ApplicationService {
    public void authenticateUser(String username, String password) { /* auth */ }
    public void processOrder(Long orderId) { /* order processing */ }
    public void sendEmail(String to, String subject) { /* email */ }
    public void generateInvoice(Long orderId) { /* invoice */ }
    public void logActivity(String message) { /* logging */ }
    public void validatePayment(Long paymentId) { /* payment */ }
    // 50 more unrelated methods... Low cohesion, high coupling
}

// REFACTORED - Good: focused services with high cohesion
@Service
class AuthenticationService {
    public void authenticate(String username, String password) { /* auth only */ }
}

@Service
class OrderService {
    private final EmailService emailService; // Loose coupling via DI
    private final InvoiceService invoiceService;

    public OrderService(EmailService emailService, InvoiceService invoiceService) {
        this.emailService = emailService;
        this.invoiceService = invoiceService;
    }

    public void processOrder(Long orderId) { /* order processing */ }
}

// Interface defines the contract
interface PaymentProcessor {
    boolean processPayment(Long orderId, BigDecimal amount);
}

// Concrete implementations - OrderService doesn't know these exist
@Service
class StripePaymentProcessor implements PaymentProcessor {
    public boolean processPayment(Long orderId, BigDecimal amount) {
        // Stripe API calls
        return true;
    }
}

@Service
class PayPalPaymentProcessor implements PaymentProcessor {
    public boolean processPayment(Long orderId, BigDecimal amount) {
        // PayPal API calls
        return true;
    }
}

// Service depends on interface, not concrete class
@Service
class OrderService {
    private final PaymentProcessor paymentProcessor; // Interface type

    public OrderService(PaymentProcessor paymentProcessor) { // Spring injects implementation
        this.paymentProcessor = paymentProcessor;
    }

    public void checkout(Long orderId, BigDecimal amount) {
        boolean success = paymentProcessor.processPayment(orderId, amount);
        // OrderService doesn't care if it's Stripe or PayPal - loose coupling
    }
}
